(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let active=null,audio=null,token=0,lastSaved=0;
function stop(){token++;if(audio){if(active&&!audio.ended){active.s.time=audio.currentTime;save();}audio.pause();audio=null;}}
function defaults(f){if(['rc','three','continuity','rl'].includes(f))return{value:0.2,min:0,max:f==='rl'?2:1,step:0.02,label:'Elapsed time t',unit:'s'};if(['sine','phasor'].includes(f))return{value:30,min:-90,max:90,step:5,label:'Phase φ',unit:'°'};if(f==='power')return{value:60,min:-80,max:80,step:5,label:'Voltage–current phase φ',unit:'°'};if(f==='series-ac')return{value:60,min:0,max:100,step:1,label:'Inductive reactance XL',unit:'Ω'};if(f==='parallel-ac')return{value:20,min:5,max:80,step:1,label:'Branch resistance R',unit:'Ω'};if(f==='ac-elements')return{value:20,min:5,max:80,step:1,label:'Impedance magnitude',unit:'Ω'};return{value:12,min:0,max:24,step:1,label:'Supply voltage',unit:'V'};}
function saved(id,g){const all=CircuitStore.get('guided')||{},raw=all[id]||{},d=defaults(g.family);return{step:Math.max(0,Math.min(3,Math.trunc(Number(raw.step)||0))),value:Number.isFinite(raw.value)?Math.max(d.min,Math.min(d.max,raw.value)):d.value,time:Number(raw.time)||0,speed:[0.8,1,1.2].includes(raw.speed)?raw.speed:1,auto:raw.auto===true,choice:Number.isInteger(raw.choice)?raw.choice:null,collapsed:raw.collapsed===true};}
function save(){if(!active)return;const all=CircuitStore.get('guided')||{};all[active.id]=active.s;CircuitStore.set('guided',all);}
const fmt=(v,d=2)=>Number(v).toFixed(d).replace(/\.00$/,'');
function model(f,v,step){
 if(['rc','three','continuity'].includes(f)){const initial=f==='three'?2:f==='continuity'?3:0,tau=.2,u=10+(initial-10)*Math.exp(-v/tau),i=(10-initial)/2*Math.exp(-v/tau);return{metrics:[['τ = RC','0.20 s'],['uC(t)',fmt(u)+' V'],['i(t)',fmt(i)+' mA']],formula:`uC(t) = 10 + (${initial} − 10)e^(−t/0.2) V`,detail:`t = ${fmt(v)} s = ${fmt(v/tau)}τ. Initial voltage ${initial} V; final voltage 10 V.`,initial,u,tau,t:v};}
 if(f==='rl'){const i=2*Math.exp(-v/.5),u=-2*i,energy=.5*i*i;return{metrics:[['τ = L/R','0.50 s'],['iL(t)',fmt(i)+' A'],['uL(t)',fmt(u)+' V']],formula:'iL(t) = 2e^(−t/0.5) A',detail:`Energy remaining: ${fmt(energy,3)} J. Passive inductor voltage uL = L di/dt = −2iL.`,i,u,tau:.5,t:v};}
 if(['sine','phasor'].includes(f)){const mag=10/Math.sqrt(2),rad=v*Math.PI/180;return{metrics:[['Peak voltage','10 V'],['RMS magnitude',fmt(mag)+' V'],['Phase',fmt(v,0)+'°']],formula:`u(t) = 10 sin(100πt ${v<0?'−':'+'} ${Math.abs(v)}°) V`,detail:`RMS phasor = ${fmt(mag*Math.cos(rad))} ${v<0?'−':'+'} j${fmt(Math.abs(mag*Math.sin(rad)))} V. Frequency = 50 Hz; period = 20 ms.`,angle:v,mag};}
 if(f==='power'){const rad=v*Math.PI/180,p=200*Math.cos(rad),q=200*Math.sin(rad);return{metrics:[['Real power P',fmt(p)+' W'],['Reactive power Q',fmt(q)+' var'],['Apparent power S','200 VA']],formula:'P = UI cosφ; Q = UI sinφ; S² = P² + Q²',detail:`U = 100 V RMS; I = 2 A RMS. Power factor = ${fmt(Math.cos(rad),3)}. ${v<0?'Negative Q: capacitive.':v>0?'Positive Q: inductive.':'Unity power factor.'}`,angle:v,p,q,mag:200};}
 if(f==='series-ac'){const x=v-20,z=Math.hypot(30,x),angle=Math.atan2(x,30)*180/Math.PI;return{metrics:[['|Z|',fmt(z)+' Ω'],['|I|',fmt(100/z)+' A RMS'],['∠Z',fmt(angle)+'°']],formula:`Z = 30 ${x<0?'−':'+'} j${Math.abs(x)} Ω`,detail:`XL = ${v} Ω; XC = 20 Ω. ${x>0?'Current lags voltage.':x<0?'Current leads voltage.':'Current and voltage are in phase.'}`,angle,real:30,imag:x,mag:z};}
 if(f==='parallel-ac'){const re=100/v,im=-5,total=Math.hypot(re,im),angle=Math.atan2(im,re)*180/Math.PI;return{metrics:[['IR',fmt(re)+' A'],['IL','5 A, −90°'],['|I total|',fmt(total)+' A']],formula:`I = ${fmt(re)} − j5 A`,detail:`100 V RMS across R = ${v} Ω and XL = 20 Ω. Total current angle ${fmt(angle)}°. Add phasors, not magnitudes.`,angle,real:re,imag:im,mag:total};}
 if(f==='ac-elements'){const angle=step===1?90:step===2?-90:0;return{metrics:[['|U|','100 V RMS'],['|Z|',v+' Ω'],['|I|',fmt(100/v)+' A RMS']],formula:step===1?`ZL = +j${v} Ω`:step===2?`ZC = −j${v} Ω`:`ZR = ${v} Ω`,detail:'Voltage is the reference. Current angle is the negative of the impedance angle. Step 2 shows L; step 3 shows C; steps 1 and 4 show R.',angle:-angle,mag:100/v};}
 if(f==='elements')return{metrics:[['R = 6 Ω, P',fmt(v*v/6)+' W'],['C = 100 µF, stored energy',fmt(.05*v*v)+' mJ'],['L = 1 H at i = 2 A','2 J']],formula:'uR = Ri; wC = ½Cu²; wL = ½Li²',detail:'Three separate examples, not a series connection: the slider sets the voltage across the 6 Ω resistor and the 100 µF capacitor. Inductor current is held at 2 A.'};
 if(f==='conditions'&&step===1)return{metrics:[['Load current','0 A'],['Open voltage',v+' V'],['State','Open']],formula:'i = 0; terminal voltage may be nonzero',detail:'Open circuit: the path is interrupted.'};
 if(f==='conditions'&&step===2)return{metrics:[['Short voltage','0 V'],['Source current',v===0?'Undetermined':'No finite solution'],['State','Ideal short']],formula:'An ideal nonzero voltage source cannot be shorted consistently',detail:'Real internal resistance or protection is required to determine a finite short-circuit current.'};
 if(f==='thevenin'&&step<2)return{metrics:[['V open-circuit',v+' V'],['R Thévenin','2 Ω'],['Load current','0 A']],formula:'VTh = Voc; RTh = 2 Ω',detail:'The load is removed, so no current flows. The open-port voltage equals the source voltage in this illustrative equivalent circuit.',i:0};
 const total=f==='parallel'?v/6+v/3:f==='superposition'?(v-6)/6:v/6;
 const metrics=f==='superposition'?[['First contribution I1',fmt(v/6)+' A'],['Second contribution I2','−1 A'],['Total current',fmt(total)+' A']]:f==='parallel'?[['I through 6 Ω',fmt(v/6)+' A'],['I through 3 Ω',fmt(v/3)+' A'],['Source current',fmt(total)+' A']]:f==='transform'?[['V Thévenin',v+' V'],['R equivalent','6 Ω'],['I Norton',fmt(v/6)+' A']]:f==='thevenin'||f==='loop'?[['Current',fmt(total)+' A'],['2 Ω drop',fmt(total*2)+' V'],['4 Ω drop',fmt(total*4)+' V']]:[['Voltage',v+' V'],['Current',fmt(total)+' A'],['Resistor power',fmt(total*total*6)+' W']];
 return{metrics,formula:f==='parallel'?'Is = U/6 + U/3':f==='superposition'?(step===1?`I1 = ${v}/6 = ${fmt(v/6)} A`:`I = (${v} − 6)/6 = ${fmt(total)} A`):f==='transform'?'IN = VTh/RTh':f==='thevenin'?'IL = VTh/(RTh + RL)':f==='loop'?'U − 2I − 4I = 0':'I = U/R; P = UI',detail:f==='superposition'?'The second 6 V source opposes the adjustable source. Signed current contributions add.':f==='thevenin'?'Two ohms of Thévenin resistance in series with a four ohm load.':f==='loop'?'Two and four ohms are in series. Their drops sum to the supply.':f==='parallel'?'Both branches share the same two nodes and the same voltage.':'Illustrative ideal circuit. The displayed values update when you change the slider.',i:total};
}
function svgWrap(content,label){return `<svg class="guided-svg" viewBox="0 0 640 330" role="img" aria-label="${esc(label)}">${content}</svg>`;}
const text=(x,y,t,cls='')=>`<text x="${x}" y="${y}" class="${cls}">${esc(t)}</text>`;
const path=(d,cls='wire')=>`<path d="${d}" class="${cls}"/>`;
function resistor(x,y,label,vertical=false,highlight=false){return `<g class="${highlight?'highlight':''}" transform="translate(${x} ${y}) ${vertical?'rotate(90)':''}">${path('M0 0h15l8 -12 12 24 12 -24 12 24 12 -24 8 12h15','component')}${text(15,-25,label)}</g>`;}
function source(x,y,label,highlight=false){return `<g class="${highlight?'highlight':''}"><circle class="component" cx="${x}" cy="${y}" r="29"/>${text(x-8,y-5,'+')}${text(x-8,y+20,'−')}${text(x-55,y-45,label)}</g>`;}
function circuit(f,v,step,m){const isRC=['rc','three','continuity'].includes(f),isRL=f==='rl';let p='';
 if(f==='elements'){p=text(35,32,'Three ideal element laws');p+=resistor(70,110,'R',false,step===0);p+=path('M250 110h45m0 -25v50m15 -50v50m0 -25h45','component');p+=text(285,65,'C');p+=path('M440 110h15q0 -25 15 -25t15 25q0 -25 15 -25t15 25q0 -25 15 -25t15 25h15','component');p+=text(480,65,'L');p+=text(45,185,'u = Ri')+text(230,185,'i = C du/dt')+text(430,185,'u = L di/dt');p+=text(120,265,'Resistor: dissipates. Capacitor and inductor: store energy.','caption');return svgWrap(p,'Resistor, capacitor, and inductor symbols and their element laws');}
 if(f==='transform'&&step>=1){p=path('M125 130V60H500M125 190V265H500');p+='<circle class="component" cx="500" cy="60" r="5"/><circle class="component" cx="500" cy="265" r="5"/>'; p+=`<circle class="component highlight" cx="125" cy="160" r="30"/>`+path('M125 180v-40m-8 10 8 -10 8 10','accent-line');p+=text(50,110,fmt(v/6)+' A');p+=path('M330 60v50m0 94v61')+resistor(330,110,'6 Ω',true,true);p+=text(480,42,'a')+text(480,299,'b')+text(370,170,'Uab = '+v+' V');return svgWrap(p,'Norton equivalent current source with a parallel six ohm resistance');}
 p+=path(isRL?'M90 60H220m94 0H500v50M500 210v55H90V60':'M90 130V60H220m94 0H500v50M500 210v55H90V190');
 if(!isRL)p+=source(90,160,isRC?'10 V':v+' V',step===0||(f==='superposition'&&step===1));else p+=text(45,160,'i(0⁺) = 2 A');
 const double=['loop','thevenin'].includes(f);p+=resistor(220,60,isRC?'2 kΩ':isRL?'2 Ω':double?'2 Ω':'6 Ω',false,step===1||step===2);
 if(f==='parallel'){p=path('M90 130V60H510M90 190V265H510')+source(90,160,v+' V',step===0)+path('M310 60v50m0 94v61M510 60v50m0 94v61')+resistor(310,110,'6 Ω',true,step===1)+resistor(510,110,'3 Ω',true,step===2);p+=text(215,300,'Is = I1 + I2');}
 else if(f==='superposition')p+=step===1?path('M500 110V210')+text(350,235,'Second source set to 0 V','caption'):path('M500 110v20m0 60v20')+source(500,160,'6 V',step===2)+text(245,305,'Sources oppose');
 else if(isRC){p+=path('M500 110v40m-28 0h56m-56 18h56m-28 0v42','component');p+=text(390,195,'100 µF')+text(370,230,'uC = '+fmt(m.u)+' V');}
 else if(isRL){p+=path('M500 110v14q-22 0 -22 12t22 12q-22 0 -22 12t22 12q-22 0 -22 12t22 12v14','component');p+=text(535,155,'1 H')+text(305,300,'iL = '+fmt(m.i)+' A');}
 else if(double){if(f==='thevenin'&&step<2)p+='<circle class="component" cx="500" cy="110" r="5"/><circle class="component" cx="500" cy="210" r="5"/>'+text(370,165,'Load removed','caption');else p+=resistor(500,110,'4 Ω',true,step>=2)+path('M500 204v6');if(f==='thevenin')p+=`<rect x="40" y="10" width="330" height="295" rx="12" class="port"/>`+text(130,307,'Thévenin network','caption');}
 else if(f==='conditions'&&step===1)p+=path('M500 110v25m0 55v20m0 -75 32 35','accent-line')+text(400,235,'OPEN');
 else if(f==='conditions'&&step===2){p=path('M90 130V60H500V265H90V190')+source(90,160,v+' V',true)+text(320,150,'SHORT')+text(220,190,'No finite ideal current','caption');}
 else p+=path('M500 110V210');
 p+=text(375,30,'i →','caption')+text(65,303,'0 V reference','caption');return svgWrap(p,'Illustrative '+f+' circuit; highlighted components follow the explanation step');
}
function acCircuit(f,v,step){let p=path('M75 130V65H150M545 65V265H75V190');p+='<circle class="component" cx="75" cy="160" r="30"/>'+text(60,169,'∿')+text(20,110,'100 V RMS');
 if(f==='series-ac'){p+=resistor(150,65,'30 Ω',false,step===0)+path('M244 65H290m0 0q0 -22 15 -22t15 22q0 -22 15 -22t15 22h55m0 -22v44m16 -44v44m0 -22H545','component')+text(290,30,'XL = '+v+' Ω')+text(410,30,'XC = 20 Ω');}
 else if(f==='parallel-ac'){p=path('M75 130V65H510M75 190V265H510')+'<circle class="component" cx="75" cy="160" r="30"/>'+text(60,169,'∿')+text(20,110,'100 V RMS')+path('M300 65v45m0 94v61M510 65v45m0 94v61')+resistor(300,110,v+' Ω',true,step===1)+path('M510 110q-22 0 -22 15t22 15q-22 0 -22 15t22 15q-22 0 -22 15t22 15v4','component')+text(415,235,'XL = 20 Ω');}
 else{if(step===1)p+=path('M150 65h30q0 -25 18 -25t18 25q0 -25 18 -25t18 25q0 -25 18 -25t18 25H545','component')+text(200,30,'XL = '+v+' Ω');else if(step===2)p+=path('M150 65h90m0 -25v50m20 -50v50m0 -25H545','component')+text(200,25,'XC = '+v+' Ω');else p+=resistor(150,65,'R = '+v+' Ω',false,true)+path('M244 65H545');p+=text(190,200,step===1?'Ideal inductor: Z = +jX':step===2?'Ideal capacitor: Z = −jX':'Resistor: Z = R','caption');}
 return svgWrap(p,'Illustrative alternating current circuit with its component values');}
function plot(f,v,m,step){if(['rc','three','continuity','rl'].includes(f)){const rl=f==='rl',maxT=rl?2:1,scale=rl?100:20,value=rl?m.i:m.u;let points='';for(let i=0;i<=100;i++){const t=i/100*maxT,val=rl?2*Math.exp(-t/.5):10+(m.initial-10)*Math.exp(-t/.2);points+=(i?'L':'M')+(65+i*5)+','+(260-val*scale);}
 return svgWrap(path('M65 40V260H580')+path(points,'response-line')+path(`M${65+v/maxT*500} 260V${260-value*scale}`,'accent-line')+`<circle class="marker" cx="${65+v/maxT*500}" cy="${260-value*scale}" r="7"/>`+text(30,30,rl?'iL (A)':'uC (V)')+text(495,300,'time (s)')+text(70,290,'0')+text(520,290,String(maxT)),rl?'Inductor current decays exponentially from two amperes':'Capacitor voltage approaches ten volts exponentially');}
 if(f==='sine'){const phi=v*Math.PI/180;let d='';for(let i=0;i<=200;i++){d+=(i?'L':'M')+(55+i*2.6)+','+(165-95*Math.sin(i/200*4*Math.PI+phi));}return svgWrap(path('M55 40V280M55 165H590')+path(d,'response-line')+text(50,30,'u (V)')+text(505,310,'time')+text(65,60,'10 V peak'),'Sinusoid shifts horizontally as phase changes');}
 const angle=(m.angle||0)*Math.PI/180,ox=200,oy=165,len=140,ex=ox+len*Math.cos(angle),ey=oy-len*Math.sin(angle),power=f==='power';
 return svgWrap(path(`M55 ${oy}H565M${ox} 290V35`)+path(`M${ox} ${oy}H${ex}V${ey}`,'projection')+path(`M${ox} ${oy}L${ex} ${ey}`,'response-line')+`<circle class="marker" cx="${ex}" cy="${ey}" r="6"/>`+text(480,205,power?'P (W)':'Real')+text(145,35,power?'Q (var)':'Imaginary')+text(ex+12,ey-12,power?'S = 200 VA':fmt(m.angle||0)+'°')+text(230,300,power?'S² = P² + Q²':'Phase angle and sign matter','caption'),power?'Power triangle with real and reactive power components':'Complex-plane vector and its projections');
}
function draw(){const{id,g,s}=active,d=defaults(g.family),st=g.steps[s.step],m=model(g.family,s.value,s.step);const host=$('#guided-host');if(!host)return;host.classList.toggle('guide-collapsed',s.collapsed);
 host.innerHTML=`<div class="guided-heading"><div><span class="chapter-tag">EXPLAINED WITH VOICE & DIAGRAMS</span><h2>${esc(g.title)}</h2></div><button id="guide-collapse" aria-expanded="${!s.collapsed}">${s.collapsed?'Open explanation':'Hide explanation'}</button></div><div class="guided-body" ${s.collapsed?'hidden':''}><div class="guide-steps" role="group" aria-label="Explanation steps">${g.steps.map((st,i)=>`<button data-guide-step="${i}" class="${i===s.step?'active':''}" aria-pressed="${i===s.step}"><span>0${i+1}</span>${esc(st.title)}</button>`).join('')}</div><div class="guide-grid"><div class="guide-visual"><div class="guide-diagrams">${['sine','phasor','ac-elements','series-ac','parallel-ac','power'].includes(g.family)?(['series-ac','parallel-ac','ac-elements'].includes(g.family)?acCircuit(g.family,s.value,s.step):'')+plot(g.family,s.value,m,s.step):circuit(g.family,s.value,s.step,m)}${['rc','three','continuity','rl'].includes(g.family)?plot(g.family,s.value,m,s.step):''}</div><div class="guide-parameter"><label for="guide-value">${d.label}<strong id="guide-value-label">${s.value} ${d.unit}</strong></label><input type="range" id="guide-value" min="${d.min}" max="${d.max}" step="${d.step}" value="${s.value}"><button id="guide-reset">Reset example</button></div><div class="guide-metrics">${m.metrics.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><div class="guide-formula">${esc(m.formula)}</div><p class="guide-model-note">${esc(m.detail)}</p></div><div class="guide-narration"><span class="eyebrow">STEP ${s.step+1} OF 4 · ILLUSTRATIVE EXAMPLE</span><h3>${esc(st.title)}</h3><p>${esc(st.text)}</p><div class="guide-audio-controls"><button id="guide-play" class="button primary">▶ Play explanation</button><button id="guide-pause" class="button">Pause</button><button id="guide-replay" class="button">Replay step</button></div><p id="guide-audio-status" role="status">${s.time>0?'Saved position: '+Math.floor(s.time)+' seconds. Press Play to continue.':'Press Play to hear this step. Audio never starts automatically on refresh.'}</p><label class="guide-speed">Voice speed<select id="guide-speed"><option value="0.8">Slower</option><option value="1">Normal</option><option value="1.2">Faster</option></select></label><label class="guide-auto"><input type="checkbox" id="guide-auto" ${s.auto?'checked':''}> Advance diagrams with narration</label><div class="guide-next"><button id="guide-prev" ${s.step===0?'disabled':''}>← Previous step</button><button id="guide-next" ${s.step===3?'disabled':''}>Next step →</button></div>${s.step===3?`<div class="guide-check"><h4>Try one prediction</h4><p>${esc(g.check.question)}</p>${g.check.options.map((o,i)=>`<button data-guide-answer="${i}" aria-pressed="${s.choice===i}">${esc(o)}</button>`).join('')}${s.choice!==null?`<p class="guide-check-feedback" role="status"><strong>${s.choice===g.check.answer?'Correct.':'Compare the reasoning.'}</strong> ${esc(g.check.why)}</p>`:''}</div>`:''}<p class="guide-disclaimer">Move the slider to explore this example. Narration describes the method; the numbers above update live. Reset returns the example to its default values.</p></div></div></div>`;
 const transport=document.createElement('div');transport.className='guide-transport';for(const selector of ['.guide-audio-controls','#guide-audio-status','.guide-speed','.guide-auto'])transport.append(host.querySelector(selector));const player=document.createElement('div');player.id='guide-audio-slot';player.className='guide-native-player';transport.append(player);host.querySelector('.guide-grid').before(transport);
 $('#guide-collapse').onclick=()=>{stop();s.collapsed=!s.collapsed;save();draw();};host.querySelectorAll('[data-guide-step]').forEach(b=>b.onclick=()=>stepTo(Number(b.dataset.guideStep)));$('#guide-prev').onclick=()=>stepTo(s.step-1);$('#guide-next').onclick=()=>stepTo(s.step+1);
 $('#guide-speed').value=String(s.speed);$('#guide-speed').onchange=e=>{s.speed=Number(e.target.value);if(audio)audio.playbackRate=s.speed;save();};$('#guide-auto').onchange=e=>{s.auto=e.target.checked;save();};$('#guide-value').oninput=e=>{s.value=Number(e.target.value);save();updateVisual();};$('#guide-reset').onclick=()=>{s.value=d.value;save();updateVisual();};
 $('#guide-play').onclick=play;$('#guide-pause').onclick=()=>{if(audio){audio.pause();s.time=audio.currentTime;save();}$('#guide-audio-status').textContent='Paused. Your place is saved.';};$('#guide-replay').onclick=()=>{stop();s.time=0;save();play();};host.querySelectorAll('[data-guide-answer]').forEach(b=>b.onclick=()=>{stop();s.choice=Number(b.dataset.guideAnswer);save();draw();});}
function updateVisual(){const {g,s}=active,d=defaults(g.family),m=model(g.family,s.value,s.step);$('#guide-value').value=s.value;$('#guide-value-label').textContent=s.value+' '+d.unit;$('.guide-diagrams').innerHTML=['sine','phasor','ac-elements','series-ac','parallel-ac','power'].includes(g.family)?(['series-ac','parallel-ac','ac-elements'].includes(g.family)?acCircuit(g.family,s.value,s.step):'')+plot(g.family,s.value,m,s.step):circuit(g.family,s.value,s.step,m)+(['rc','three','continuity','rl'].includes(g.family)?plot(g.family,s.value,m,s.step):'');$('.guide-metrics').innerHTML=m.metrics.map(([l,v])=>`<div><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('');$('.guide-formula').textContent=m.formula;$('.guide-model-note').textContent=m.detail;}
function stepTo(n){if(n<0||n>3)return;stop();active.s.step=n;active.s.time=0;save();draw();}
async function play(){if(!active)return;if(audio&&!audio.ended){audio.playbackRate=active.s.speed;try{await audio.play();$('#guide-audio-status').textContent='Playing explanation…';}catch(error){console.warn('Narration playback failed',error.name,error.message);$('#guide-audio-status').textContent='Audio could not start. Try Replay step.';}return;}const current=token,{id,g,s}=active;audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=g.steps[s.step].audio;audio.setAttribute('aria-label','Narration for '+g.steps[s.step].title);$('#guide-audio-slot').replaceChildren(audio);audio.playbackRate=s.speed;audio.onloadedmetadata=()=>{if(current===token&&s.time>0&&s.time<audio.duration)audio.currentTime=s.time;};audio.onpause=audio.onseeked=()=>{if(current===token){s.time=audio.currentTime;save();}};audio.ontimeupdate=()=>{if(current!==token)return;if(Date.now()-lastSaved>700){lastSaved=Date.now();s.time=audio.currentTime;save();}};audio.onended=()=>{if(current!==token)return;s.time=0;save();if(s.auto&&s.step<3){stepTo(s.step+1);play();}else $('#guide-audio-status').textContent='Step finished. Explore the diagram or choose the next step.';};audio.onerror=()=>{if(current===token)$('#guide-audio-status').textContent='Could not load narration. Your step is saved. Use the written explanation and try Replay.';};try{await audio.play();$('#guide-audio-status').textContent='Playing explanation…';}catch(error){console.warn('Narration playback failed',error.name,error.message);$('#guide-audio-status').textContent='Audio could not start. Try Replay step.';}}
function mount(){stop();active=null;const match=location.hash.match(/^#topic\/([\d.]+)$/),id=match?.[1],g=window.CIRCUIT_GUIDES?.[id];if(!g||!$('.article'))return;active={id,g,s:saved(id,g)};const host=document.createElement('section');host.id='guided-host';const slot=$('#course-guided-slot');if(slot)slot.append(host);else const slot=$('#course-guided-slot');if(slot)slot.append(host);else $('.article').before(host);draw();}
window.CircuitGuided={mount,stop,model};window.addEventListener('hashchange',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio){audio.pause();if(active){active.s.time=audio.currentTime;save();}}});
})();
